effect.shader:
const int TAPS = 8;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  vec4 blur = vec4(0.0);
  for (int i = 0; i < TAPS; i++){
    float ang = float(i) * 6.2831853 / float(TAPS);
    blur += texture2DCv(inputImg.texture, uv + vec2(cos(ang), sin(ang)) * radius);
  }
  blur /= float(TAPS);
  float a = max(src.a, 1e-4);
  vec3 sc = src.rgb / a;
  vec3 bc = blur.rgb / max(blur.a, 1e-4);
  vec3 detail = sc - bc;
  float m = smoothstep(threshold, threshold + 0.05, length(detail));
  vec3 g = clamp(sc + detail * amount * m * mixAmt, 0.0, 1.0);
  gl_FragColor = vec4(g * a, a);
}
